// The standard library reference, generated by scripts/gen-stdlib.mjs from `zell doc std --json`.
import index from "../../generated/stdlib/index.json";

export type Kind = "const" | "func" | "struct" | "interface" | "enum" | "field" | "method" | "variant";

export interface ApiExample { name: string; target: string; suffix: string; code: string; output: string; unordered: boolean }

export interface ApiItem {
  name: string;
  kind: Kind;
  signature: string;
  doc: string;
  summary: string;
  file: string;
  line: number;
  members?: ApiItem[];
  examples?: ApiExample[];
}

export interface Namespace { name: string; doc: string; files: string[]; items: ApiItem[] }

export interface NamespaceEntry { name: string; summary: string; symbols: { name: string; kind: Kind; summary: string }[] }

export const STD_VERSION: string = index.zell;
export const NAMESPACES = index.namespaces as NamespaceEntry[];

const files = import.meta.glob<Namespace>("../../generated/stdlib/ns/*.json", { import: "default" });

/** Loads one namespace's full data (a separate chunk per namespace). */
export function loadNamespace(name: string): Promise<Namespace> | null {
  const load = files[`../../generated/stdlib/ns/${name}.json`];
  return load ? load() : null;
}

/** Source link at the release tag, so line numbers match the documented version. */
export const sourceUrl = (file: string, line: number) =>
  `https://github.com/zell-lang/zell/blob/v${STD_VERSION}/${file}#L${line}`;

/** The first segment groups namespaces: crypto.aes and crypto.rsa under "crypto". */
export const groupOf = (ns: string) => ns.split(".")[0];

export const KIND_TITLES: [Kind[], string][] = [
  [["const"], "Constants"],
  [["struct", "interface", "enum"], "Types"],
  [["func"], "Functions"],
];
